import { test } from 'node:test';
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import { join, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';
import { discoverPacks } from '../engine/pack_loader/pack-registry.mjs';
import { packRules } from '../engine/checks/run-active-pack-rules.mjs';

// packs/README.md's corpus tally quotes how many hardcoded checks the canon
// carries — a derived number that was hand-maintained and drifted badly (it
// read 41 while the runner listed 65, so the ratio it argues from was wrong by
// a third). The catalog is the single source of truth; this guard keeps the
// prose equal to it. `packRules` is the same assembly `--list` prints, so the
// tally can never disagree with the runner about what a rule is.
//
// Deliberately guards only the CHECK count. The prose-rule figures beside it
// are audit estimates from docs/conversion-inventory.md — nothing derives them,
// so the README marks them as a dated snapshot rather than pretending they are
// live, and no test can hold them honest.
const ROOT = join(dirname(fileURLToPath(import.meta.url)), '..');
const CATALOG = 'packs/README.md';
const TALLY = /\|\s*\*\*Hardcoded conformance checks\*\*\s*\|\s*\*\*(\d+)\*\*/;

test('the packs/ catalog tally equals the rule catalog the runner lists', async () => {
  const { packs } = await discoverPacks({ localRoot: ROOT });
  const actual = packRules(packs).length;

  const readme = readFileSync(join(ROOT, CATALOG), 'utf8');
  const m = TALLY.exec(readme);
  assert.ok(m, `${CATALOG} carries no parseable "Hardcoded conformance checks" tally — keep the bolded count in the corpus-tally table so this guard can read it`);
  assert.equal(
    Number(m[1]), actual,
    `${CATALOG} says ${m[1]} hardcoded checks; the catalog carries ${actual}. Update the tally (and the ratio it feeds) in the same change that adds or removes a rule.`
  );
});

import { join, dirname } from 'node:path';
import { finding } from '../../../../engine/checks/helpers/findings.mjs';
import { matchingLines, ruleIdsIn } from '../../../../engine/checks/helpers/line-scanning.mjs';

// A pack's injected prose must not narrate its own enforcement: checks run on
// their own at every Stop and in CI, and each failure message carries its
// rule. Scans exactly the file each pack.mjs declares as `prose`, never the
// pack README — the catalog convention *requires* the README to list the
// pack's rules and how each is enforced. Home-only by declaration:
// canon-curation is declared solely in the canon home repo, which gates this
// rule for free.
const RUNNER = /checks\/run\.mjs/;
const asWord = (id) => new RegExp(`(^|[^\\w-])${id}([^\\w-]|$)`); // never inside a longer kebab name

const rule = {
  id: 'pack-no-enforcement-narration',
  severity: 'blocking',
  description: "A pack's injected prose neither tells the reader to run the checks runner nor names the rules the pack's own checks enforce",
  doc: 'engine/checks/DESIGN.md',
  why: 'checks run automatically at every Stop and in CI, and each failure message carries its rule — prose narrating its own enforcement duplicates the mechanism and drifts from it',

  run(ctx) {
    const docs = ctx.files
      .filter((f) => /^packs\/[^/]+\/pack\.mjs$/.test(f))
      .flatMap((f) => {
        const m = /\bprose:\s*'([^']+)'/.exec(ctx.read(f) ?? '');
        return m ? [join(dirname(f), m[1])] : [];
      });
    return [
      ...matchingLines(ctx, docs, RUNNER).map(({ file, line }) => finding(rule, {
        file, line,
        what: 'tells the reader to run the checks runner',
        fix: 'delete the instruction — the Stop hook and CI run every check on their own',
      })),
      ...docs.flatMap((doc) => [...ruleIdsIn(ctx, dirname(doc))].sort().flatMap((id) =>
        matchingLines(ctx, [doc], asWord(id)).map(({ file, line }) => finding(rule, {
          file, line,
          what: `names its own check rule "${id}"`,
          fix: 'remove the mention — the rule announces itself when it fires, and its failure message carries the instruction',
        })))),
    ];
  },
};

export default rule;

import { finding } from '../../engine/checks/helpers/findings.mjs';

const rule = {
  id: 'task-lifecycle',
  severity: 'blocking',
  description: 'Work on a branch must reference a GitHub issue in at least one commit message',
  doc: 'packs/basics/RULES.md',
  scope: 'work',
  why: 'every task starts from an issue; the reference is what ties the branch to it',

  run(work) {
    const { commits } = work;
    if (work.onDefaultBranch() || !commits.length || commits.some((m) => /#\d+/.test(m))) return [];
    return [finding(rule, {
      file: '(branch)',
      what: `none of the ${commits.length} commit(s) since ${work.baseRef} references an issue (#N)`,
      fix: 'create or locate the GitHub issue for this task and reference it (e.g. "Refs #N", "Closes #N") in a commit message — amending the latest commit is fine',
    })];
  },
};

export default rule;

